// Screen-space annotation layout: small candidate searches with stable identities.
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const rect=(p,w,h)=>({x:p.x-w/2,y:p.y-h/2,w,h});
const overlaps=(a,b)=>a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;
function segmentRect(a,b,r){let lo=0,hi=1;const dx=b.x-a.x,dy=b.y-a.y;for(const [p,q]of [[-dx,a.x-r.x],[dx,r.x+r.w-a.x],[-dy,a.y-r.y],[dy,r.y+r.h-a.y]]){if(Math.abs(p)<1e-9){if(q<0)return false;}else{const t=q/p;if(p<0)lo=Math.max(lo,t);else hi=Math.min(hi,t);if(lo>hi)return false;}}return true;}
export function polarCandidates(anchor,angle,radius,{spread=.25,step=9,rings=4}={}){const out=[];for(const r of Array.from({length:rings},(_,i)=>radius+i*step))for(const turn of [0,-spread,spread,-2*spread,2*spread])out.push({x:anchor.x+Math.cos(angle+turn)*r,y:anchor.y+Math.sin(angle+turn)*r});return out;}
export function edgeCandidates(a,b,sign=1){const d=distance(a,b)||1,t={x:(b.x-a.x)/d,y:(b.y-a.y)/d},mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2},out=[];for(const r of [18,26,34,42])for(const side of [sign,-sign])for(const along of [0,-12,12])out.push({x:mid.x+t.y*r*side+t.x*along,y:mid.y-t.x*r*side+t.y*along});return out;}
export class LabelLayout {
 constructor(){this.previous=new Map();}
 begin({bounds,segments=[],points=[],arcs=[]}){this.bounds=bounds;this.segments=[...segments];for(const a of arcs){let prev;for(let i=0;i<=24;i++){const t=a.start+a.sweep*i/24,p={x:a.p.x+Math.cos(t)*a.radius,y:a.p.y+Math.sin(t)*a.radius};if(prev)this.segments.push([prev,p]);prev=p;}}this.points=points;this.placed=[];this.live=new Set();}
 score(p,w,h){const r=rect(p,w+6,h+4),v=this.bounds;let score=0;if(v){score+=Math.max(0,v.x-r.x)+Math.max(0,r.x+r.w-v.x-v.w)+Math.max(0,v.y-r.y)+Math.max(0,r.y+r.h-v.y-v.h);score*=500;}for(const [a,b]of this.segments)if(segmentRect(a,b,r))score+=160;for(const q of this.points)if(overlaps(r,rect(q,14,14)))score+=200;for(const box of this.placed)if(overlaps(r,box))score+=300;return score;}
 place({id,text,width,height=16,candidates}){const ideal=candidates[0];if(!ideal)return null;const viewport=this.bounds;if(viewport){const extra=candidates.map(p=>({x:Math.max(viewport.x+width/2+3,Math.min(viewport.x+viewport.w-width/2-3,p.x)),y:Math.max(viewport.y+height/2+2,Math.min(viewport.y+viewport.h-height/2-2,p.y))}));candidates=[...candidates,...extra.filter((p,i)=>distance(p,candidates[i])<36)];}const options=candidates.map((p,index)=>({p,index,score:this.score(p,width,height)+distance(p,ideal)*.4})).sort((a,b)=>a.score-b.score||a.index-b.index);let best=options[0],old=this.previous.get(id),previous=options.find(x=>x.index===old);if(previous&&previous.score<=best.score+9)best=previous;this.previous.set(id,best.index);this.live.add(id);this.placed.push(rect(best.p,width+6,height+4));return {id,text,...best.p,displaced:distance(best.p,ideal)>16};}
 end(){for(const id of this.previous.keys())if(!this.live.has(id))this.previous.delete(id);}
}
export function paintLabel(ctx,label,{ink='#243047',background='#fff',scale=1}={}){ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';ctx.lineJoin='round';ctx.lineWidth=3/scale;ctx.strokeStyle=background;ctx.strokeText(label.text,label.x,label.y);ctx.fillStyle=ink;ctx.fillText(label.text,label.x,label.y);ctx.restore();}
